const SPECIES=PLANT_KNOWLEDGE;
const featureCategories=[{title:"COLOUR",keys:["pink","red","yellow","blue","pale","dark"]},{title:"FLOWER SHAPE",keys:["flower_coverage","largest_component_share","boundary_ratio","flower_components"]},{title:"SURFACE",keys:["broad_surface_score","fine_texture_score"]},{title:"CENTRE",keys:["yellow_center_ratio","average_saturation","average_brightness"]},{title:"CONTEXT",keys:["green_context"]}];
function renderFeatureGroups(features){return featureCategories.map(group=>`<section class="feature-group"><h3>${group.title}</h3>${group.keys.filter(key=>key in features).map(key=>{const value=features[key];return`<div class="feature-item"><div class="feature-label"><span>${key.replaceAll("_"," ")}</span><strong>${value.toFixed(3)}</strong></div><div class="bar"><span style="width:${Math.min(100,value*100)}%"></span></div></div>`}).join("")}</section>`).join("")}
const renderTableVersion=render;
