const $=id=>document.getElementById(id),input=$("photoInput"),preview=$("preview"),processing=$("processing"),canvas=$("analysisCanvas"),ctx=canvas.getContext("2d",{willReadFrequently:true}),maskCanvas=$("maskPreview"),maskCtx=maskCanvas.getContext("2d");let lastOutput=null;
function hsv(r,g,b){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;if(d){if(max===r)h=((g-b)/d)%6;else if(max===g)h=(b-r)/d+2;else h=(r-g)/d+4;h=Math.round(h*60);if(h<0)h+=360}return[h,max===0?0:d/max,max]}
function components(mask,size){const seen=new Uint8Array(mask.length),parts=[];for(let start=0;start<mask.length;start++){if(!mask[start]||seen[start])continue;const stack=[start];seen[start]=1;let count=0;while(stack.length){const p=stack.pop(),x=p%size,y=(p/size)|0;count++;for(const n of [p-1,p+1,p-size,p+size]){if(n<0||n>=mask.length||seen[n]||!mask[n])continue;const nx=n%size,ny=(n/size)|0;if(Math.abs(nx-x)+Math.abs(ny-y)!==1)continue;seen[n]=1;stack.push(n)}}if(count>=12)parts.push(count)}return parts.sort((a,b)=>b-a)}
function colourRanker(f){return{waterlily:f.pink*1.1+f.pale*.35,dandelion:f.yellow*1.5,daisy:f.pale*1.1+f.yellow*.25,poppy:f.red*1.5,clover:f.pink*1.25,bluebell:f.blue*1.5}}
